// GenericObjectMultiError is an error wrapping multiple validation errors
// returned by GenericObject.ValidateAll() if the designated constraints
// aren't met.
type GenericObjectMultiError []error

// Error returns a concatenation of all the error messages it wraps.
func (m GenericObjectMultiError) Error() string {
	var msgs []string
	for _, err := range m {
		msgs = append(msgs, err.Error())
	}
	return strings.Join(msgs, "; ")
}

// AllErrors returns a list of validation violation errors.
func (m GenericObjectMultiError) AllErrors() []error { return m }

// GenericObjectValidationError is the validation error returned by
// GenericObject.Validate if the designated constraints aren't met.
type GenericObjectValidationError struct {
	field  string
	reason string
	cause  error
	key    bool
}

// Field function returns field value.
func (e GenericObjectValidationError) Field() string { return e.field }

// Reason function returns reason value.
func (e GenericObjectValidationError) Reason() string { return e.reason }

// Cause function returns cause value.
func (e GenericObjectValidationError) Cause() error { return e.cause }

// Key function returns key value.
func (e GenericObjectValidationError) Key() bool { return e.key }

// ErrorName returns error name.
func (e GenericObjectValidationError) ErrorName() string { return "GenericObjectValidationError" }

// Error satisfies the builtin error interface
func (e GenericObjectValidationError) Error() string {
	cause := ""
	if e.cause != nil {
		cause = fmt.Sprintf(" | caused by: %v", e.cause)
	}

	key := ""
	if e.key {
		key = "key for "
	}

	return fmt.Sprintf(
		"invalid %sGenericObject.%s: %s%s",
		key,
		e.field,
		e.reason,
		cause)
}

var _ error = GenericObjectValidationError{}

var _ interface {
	Field() string
	Reason() string
	Key() bool
	Cause() error
	ErrorName() string
} = GenericObjectValidationError{}

